<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'
const password = ref(''); const confirmation = ref(''); const code = ref(''); const error = ref(''); const busy = ref(false); const auth = useAuthStore(); const router = useRouter()
async function submit() { busy.value = true; error.value = ''; try { if (auth.setupRequired) { if (password.value !== confirmation.value) throw new Error('两次输入的密码不一致。'); await auth.setup(code.value, password.value) } else await auth.login(password.value); await router.push('/') } catch (err) { error.value = err instanceof Error ? err.message : '操作失败，请重试。' } finally { busy.value = false } }
</script>
<template><section class="login-page"><div class="login-orbit">✦</div><p class="eyebrow">你的私人放映室</p><h1>今晚，听一个<br><em>只属于你的故事。</em></h1><form v-if="!auth.setupRequired || auth.setupAvailable" @submit.prevent="submit"><template v-if="auth.setupRequired"><p class="setup-help">首次使用：请从服务启动日志中复制一次性初始化码，并设置至少 8 位密码。</p><label for="setup-code">一次性初始化码</label><input id="setup-code" v-model="code" type="text" autocomplete="one-time-code" placeholder="粘贴日志中的初始化码" required autofocus><label for="password">设置访问密码</label><input id="password" v-model="password" type="password" autocomplete="new-password" placeholder="至少 8 个字符" minlength="8" required><label for="confirmation">再次输入密码</label><input id="confirmation" v-model="confirmation" type="password" autocomplete="new-password" placeholder="确认访问密码" minlength="8" required></template><template v-else><label for="password">访问密码</label><input id="password" v-model="password" type="password" autocomplete="current-password" placeholder="输入密码" required autofocus></template><p v-if="error" class="error">{{ error }}</p><button class="primary wide" :disabled="busy">{{ busy ? '正在处理…' : auth.setupRequired ? '设置密码并进入' : '进入放映室' }}</button></form><p v-else class="error">服务配置无法读取，暂时不能初始化。请检查服务端日志或联系管理员。</p></section></template>
